'use strict';
const fs=require('node:fs');
function loadTeams(files){return files.map(file=>JSON.parse(fs.readFileSync(file,'utf8')));}
module.exports={loadTeams};

'use strict';
function mergeContacts(teams){
  const rows=new Map();
  for(const team of teams) for(const contact of team.contacts){
    const key=contact.email.trim().toLowerCase();
    const previous=rows.get(key);
    if(!previous||contact.updated_at>previous.updated_at) rows.set(key,{...contact});
  }
  return [...rows.values()];
}
module.exports={mergeContacts};

'use strict';
const columns=['contact_id','name','email','updated_at'];
const quote=value=>/[",\r\n]/.test(String(value))?'"'+String(value).replaceAll('"','""')+'"':String(value);
function toCsv(rows){return [columns.join(','),...rows.map(row=>columns.map(key=>quote(row[key])).join(','))].join('\n')+'\n';}
module.exports={toCsv};

'use strict';
const {loadTeams}=require('../src/load.cjs');
const {mergeContacts}=require('../src/merge.cjs');
const {toCsv}=require('../src/csv.cjs');
const files=process.argv.slice(2);
if(!files.length){process.stderr.write('Usage: node bin/export.cjs FILE.json [FILE.json ...]\n');process.exitCode=2;}
else process.stdout.write(toCsv(mergeContacts(loadTeams(files))));

